class Solution:
    def depthSum(self, nestedList: List[NestedInteger]) -> int:
        def dfs(items, depth):
            total = 0
            for x in items:
                if x.isInteger():
                    total += x.getInteger() * depth
                else:
                    total += dfs(x.getList(), depth + 1)
            return total
        return dfs(nestedList, 1)

