class Solution {
public:
    int depthSum(vector<NestedInteger>& nestedList) {
        function<int(const vector<NestedInteger>&, int)> dfs = [&](const vector<NestedInteger>& list, int depth) {
            int total = 0;
            for (const auto& item : list) {
                if (item.isInteger()) total += item.getInteger() * depth;
                else total += dfs(item.getList(), depth + 1);
            }
            return total;
        };
        return dfs(nestedList, 1);
    }
};

